{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C47", "C17", "C29", "C04", "C08", "C15", "C46", "C42", "C10", "C21", "C51", "C64", "C80", "C49", "C93", "C102", "C105", "C18"],
  "contradictory_card_ids": ["C52", "C55", "C109", "C43", "C14", "C01"],
  "prediction_basis_card_ids": ["C47", "C17", "C29", "C04", "C08", "C15", "C46", "C42", "C10", "C21", "C51", "C64", "C80", "C49", "C93"],
  "claims": [
    {
      "claim": "2-Methoxyestradiol, the closest estradiol analogue with the same phenolic A-ring and steroid core, has measured oral F of 1-2% in patients and 3.04% in rats with very poor rat exposure; L2 rat data reinforce the low-F direction.",
      "card_ids": ["C47", "C17", "C29", "C51", "C64"]
    },
    {
      "claim": "Danazol, a highly lipophilic steroid, has absolute oral F of 11-19% in fasted humans; L2 data show even with 1000 ml water F is only 17±3.4%, still below 20%.",
      "card_ids": ["C04", "C08", "C15", "C46", "C49", "C93"]
    },
    {
      "claim": "Progesterone clinical records report approximately 5% to less than 10% oral F; L2 rat data show 4.1±1%, reinforcing the low-F pattern for unmodified steroids.",
      "card_ids": ["C10", "C21", "C42", "C80"]
    },
    {
      "claim": "Estramustine phosphate, an estradiol prodrug, shows 34.9-56.2% F values but no parent drug was detected in plasma after oral dosing; L2 confirms the approximately 40% value reflects active metabolites, not parent prodrug, so it does not support high parent F for the query ester.",
      "card_ids": ["C38", "C02", "C28", "C40", "C48", "C18", "C109"]
    },
    {
      "claim": "Withaferin A L2 data are mixed across species with 87% and 32.4% in rats but 1.8% in mice, while the human L1 record reports poor oral bioavailability; the high rat values do not transfer to the query.",
      "card_ids": ["C52", "C55", "C102", "C105", "C34"]
    },
    {
      "claim": "High-F records for ethinyl estradiol at 51% and NOMAC at approximately 63% involve different steroids with metabolic protection or different structures and do not transfer to estradiol cypionate.",
      "card_ids": ["C14", "C43"]
    },
    {
      "claim": "The query's physicochemical prior with logD 6.13, one phenol, one ester, and no basic center predicts very poor aqueous solubility; the ester prodrug would be hydrolyzed to estradiol, which is subject to extensive first-pass metabolism, consistent with the low-F steroid records.",
      "card_ids": ["C29", "C42", "C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C51", "C64", "C80", "C49", "C93", "C102", "C105", "C109", "C52", "C55"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for estradiol cypionate itself is present in the supplied records.",
    "Dose, formulation, and prandial state for the query are unspecified; oral F of lipophilic steroids is highly formulation-dependent.",
    "The ester prodrug may be hydrolyzed before absorption; the bioavailability of the active estradiol moiety versus the parent ester is not resolved.",
    "Withaferin A rat F values of 87% and 32.4% conflict with mouse and human low-F records, limiting cross-species transfer.",
    "EMP high-F records reflect active metabolites rather than parent drug, leaving no affirmative high-F precedent for an estradiol ester parent."
  ],
  "decision_summary": "Predicted low and strengthened: L2 records add rat F values for 2-methoxyestradiol (3.04%) and progesterone (4.1%), danazol 17% even with high water volume, and withaferin A mouse F of 1.8%, all below 20%; the EMP approximately 40% value is confirmed to reflect active metabolites rather than parent drug. The closest estradiol analogues with measured oral F consistently fall below 20%, and the query's very high logD predicts poor aqueous solubility."
}

